{
  "name": "文件读写工具",
  "name_en": "File I/O Utility",
  "manufacturer": "",
  "description": "通用文件读写工具，用于实验软件中创建、选择、读取和写入数据文件。适合记录实验日志、保存测量结果，以及读取文本、CSV 和简单键值文本数据。",
  "description_en": "A general file I/O utility used in laboratory software to create, select, read, and write data files. It is suitable for experiment logging, saving measurement results, and reading text, CSV, and simple key-value text data.",
  "tag_hints": [
    "file I/O",
    "data logging",
    "text file read/write",
    "CSV parsing",
    "result storage"
  ],
  "actions": [
    {
      "action_name": "auto-makeFile",
      "description": "在给定路径所在目录中创建文件。",
      "description_en": "Create a file in the same directory as the given path."
    },
    {
      "action_name": "auto-init",
      "description": "初始化并追加写入指定名称的数据记录文件。",
      "description_en": "Initialize and append to a data log file with the specified name."
    },
    {
      "action_name": "auto-set_filename",
      "description": "设置目标文件名。",
      "description_en": "Set the target filename."
    },
    {
      "action_name": "auto-read",
      "description": "读取文件内容。",
      "description_en": "Read the file contents."
    },
    {
      "action_name": "auto-readcsv",
      "description": "读取 CSV 文件内容。",
      "description_en": "Read the contents of a CSV file."
    },
    {
      "action_name": "auto-readdict",
      "description": "读取以空格分隔的文本并解析为键值数据。",
      "description_en": "Read a space-delimited text file and parse it into key-value data."
    },
    {
      "action_name": "auto-write",
      "description": "向文件写入文本内容。",
      "description_en": "Write text content to the file."
    },
    {
      "action_name": "auto-write_raw",
      "description": "向文件写入原始文本内容。",
      "description_en": "Write raw text content to the file."
    }
  ]
}

